import sys
import os
import torch
from transformers import AutoTokenizer

# Add the export stage to path so we can import the custom model classes
sys.path.insert(0, os.path.join(os.path.dirname(__file__), "..", "..", "06_export-to-huggingface", "01_main-chapter-code"))

from configuration_fingpt import FinGPTConfig
from modeling_fingpt import FinGPTForCausalLM

# Path to the exported model folder (gitignored; generated by export_fingpt.py)
MODEL_DIR = os.path.join(os.path.dirname(__file__), "..", "..", "06_export-to-huggingface", "01_main-chapter-code", "fingpt-131m")

print("Loading config and model from", MODEL_DIR)
config = FinGPTConfig.from_pretrained(MODEL_DIR)
hf_model = FinGPTForCausalLM.from_pretrained(MODEL_DIR, config=config)
hf_model.eval()
print("Model loaded successfully.\n")

tokenizer = AutoTokenizer.from_pretrained("openai-community/gpt2")

# Mix of in-domain (GST/tax) and slightly-off-domain prompts, plus a couple
# of repeated prompts at different temperatures -- checking both "does it
# know the domain" and "does it repeat/loop regardless of what you ask".
PROMPTS = [
    ("What is GST?", 0.8),
    ("What is GST?", 0.5),                                   # same prompt, lower temp -- does repetition get worse or better?
    ("Input Tax Credit can be claimed when", 0.8),
    ("The Authority for Advance Ruling held that", 0.8),
    ("Under Section 17(5) of the CGST Act,", 0.8),
    ("The applicant is engaged in the business of", 0.8),
    ("A registered taxable person is required to", 0.8),
    ("The rate of tax applicable on the supply of", 0.8),
    ("Explain how a bicycle works.", 0.8),                    # off-domain control -- expect it to fall apart here
    ("Once upon a time,", 0.8),                                # off-domain control
]

MAX_NEW_TOKENS = 60

for i, (prompt, temperature) in enumerate(PROMPTS, 1):
    inputs = tokenizer(prompt, return_tensors="pt")
    with torch.no_grad():
        generated = hf_model.generate(
            inputs["input_ids"],
            max_new_tokens=MAX_NEW_TOKENS,
            do_sample=True,
            temperature=temperature,
            top_k=50,
        )
    text = tokenizer.decode(generated[0], skip_special_tokens=True)

    print(f"--- [{i}/{len(PROMPTS)}] temp={temperature} ---")
    print(f"Prompt:    {prompt}")
    print(f"Generated: {text}")
    print()

print("Done. Look for: (a) coherence within a sentence, (b) whether it loops")
print("on the same phrase, (c) whether in-domain prompts hold up better than")
print("the two off-domain control prompts at the end.")